// ChatHandler — append the assistant turn to the store. For chat3. Spec §3.4.
//
// id-first (spec §2): the assistant node id was generated by run() before
// generation and rides the events; the append uses that same id, so the record
// id == the id in `message_start`/`done`. The full block set (thinking / tool_use
// / text) is mapped to typed Parts; `output` is the plain text for stdout.

import type { IHandler, EngineResponse, HandlerTarget, EngineConfig, HandlerResult } from '../types.js'
import { textFromBlocks, blocksToParts } from '../parts.js'

export class ChatHandler implements IHandler {
  async handle(
    response: EngineResponse,
    target: HandlerTarget,
    config: EngineConfig,
  ): Promise<HandlerResult> {
    const output = textFromBlocks(response.content)

    // Nothing to persist (e.g. an aborted turn) — don't write an empty node.
    if (response.content.length === 0) {
      return { output, artifacts: { stopReason: response.stopReason } }
    }

    const role = typeof config['assistantRole'] === 'string' ? (config['assistantRole'] as string) : 'assistant'
    const meta: Record<string, unknown> = {}
    if (response.usage) meta['usage'] = response.usage

    const node = await target.store.appendNode(target.sessionId, {
      id: target.assistantId,
      role,
      parts: blocksToParts(response.content),
      ...(Object.keys(meta).length ? { meta } : {}),
    })

    return {
      output,
      artifacts: { id: node.id, node, usage: response.usage, stopReason: response.stopReason },
    }
  }
}
